import pandas as pd


def _plan_equal(a, b):
    a_null = pd.isna(a)
    b_null = pd.isna(b)
    if a_null and b_null:
        return True
    if a_null or b_null:
        return False
    return a == b


def _covers(start, end, d):
    if end is None or pd.isna(end):
        return start <= d
    return (start <= d) and (d < end)


def run(inputs: dict) -> dict:
    dim = inputs["DIM_ACCOUNT"].copy()
    stg = inputs["STG_ACCOUNT"].copy()

    # Normalize dtypes for processing
    if not dim.empty:
        dim["eff_start_date"] = pd.to_datetime(dim["eff_start_date"])
        dim["eff_end_date"] = pd.to_datetime(dim["eff_end_date"])
        dim["is_current"] = dim["is_current"].astype(int)
    if not stg.empty:
        stg["update_date"] = pd.to_datetime(stg["update_date"])

    # Build initial versions per account from DIM_ACCOUNT
    versions_by_account = {}
    if not dim.empty:
        for acct_id, grp in dim.groupby("account_id"):
            versions = []
            for _, row in grp.iterrows():
                versions.append(
                    {
                        "plan": row["plan"],
                        "eff_start_date": row["eff_start_date"],
                        "eff_end_date": row["eff_end_date"] if not pd.isna(row["eff_end_date"]) else None,
                        "is_current": int(row["is_current"]),
                    }
                )
            versions_by_account[acct_id] = versions

    # Build staged records per account, sorted by update_date ascending
    staged_by_account = {}
    if not stg.empty:
        stg_sorted = stg.sort_values(["account_id", "update_date"], kind="mergesort")
        for acct_id, grp in stg_sorted.groupby("account_id", sort=False):
            records = []
            for _, row in grp.iterrows():
                records.append({"plan": row["plan"], "update_date": row["update_date"]})
            staged_by_account[acct_id] = records

    all_account_ids = set(versions_by_account.keys()) | set(staged_by_account.keys())

    result_rows = []

    for acct_id in all_account_ids:
        versions = list(versions_by_account.get(acct_id, []))
        # deep-ish copy of dict entries since we mutate them
        versions = [dict(v) for v in versions]
        staged = staged_by_account.get(acct_id, [])

        for s in staged:
            s_plan = s["plan"]
            s_date = s["update_date"]

            if not versions:
                versions.append(
                    {
                        "plan": s_plan,
                        "eff_start_date": s_date,
                        "eff_end_date": None,
                        "is_current": 1,
                    }
                )
                continue

            v = None
            for ver in versions:
                if _covers(ver["eff_start_date"], ver["eff_end_date"], s_date):
                    v = ver
                    break

            if v is None:
                # earlier than the account's earliest version
                f = min(versions, key=lambda x: x["eff_start_date"])
                versions.append(
                    {
                        "plan": s_plan,
                        "eff_start_date": s_date,
                        "eff_end_date": f["eff_start_date"],
                        "is_current": 0,
                    }
                )
            else:
                if _plan_equal(v["plan"], s_plan):
                    pass
                elif s_date == v["eff_start_date"]:
                    v["plan"] = s_plan
                else:
                    versions.append(
                        {
                            "plan": s_plan,
                            "eff_start_date": s_date,
                            "eff_end_date": v["eff_end_date"],
                            "is_current": v["is_current"],
                        }
                    )
                    v["eff_end_date"] = s_date
                    v["is_current"] = 0

        for ver in versions:
            result_rows.append(
                {
                    "account_id": acct_id,
                    "plan": ver["plan"],
                    "eff_start_date": ver["eff_start_date"],
                    "eff_end_date": ver["eff_end_date"],
                    "is_current": int(ver["is_current"]),
                }
            )

    out_cols = ["account_id", "plan", "eff_start_date", "eff_end_date", "is_current"]

    if result_rows:
        out_df = pd.DataFrame(result_rows, columns=out_cols)
        out_df["eff_start_date"] = pd.to_datetime(out_df["eff_start_date"])
        out_df["eff_end_date"] = pd.to_datetime(out_df["eff_end_date"])
        out_df["is_current"] = out_df["is_current"].astype(int)
        out_df = out_df.sort_values(
            ["account_id", "eff_start_date"], kind="mergesort"
        ).reset_index(drop=True)
    else:
        out_df = pd.DataFrame(columns=out_cols)

    return {"dim_account_out": out_df}
